export function take(shelf, title) {
  const book = shelf.books[title];
  if (book === undefined) throw new RangeError("no book " + title);
  return book;
}
export class Shelf {
  books = {};
  put(title, pages) { if (pages < 0) { throw new RangeError("pages " + pages); } this.books[title] = { title, pages }; return this; }
  get first() { return Object.keys(this.books)[0].toUpperCase(); }
  each(visit) { for (const title in this.books) visit(this.books[title]); return this; }
}
export function where() { return new Error("here").stack; }
export const pagesOf = (shelf, title) => shelf.books[title].pages;
export function callMissing(shelf) { return shelf.missing(1, 2); }
export function construct(value) { return new value.Maker("é€", 1); }
export async function later(shelf, title) { await null; return take(shelf, title); }
export function tagged(tag) { return tag`a${1}b`; }
export function mapped(list) { return list.map(item => item.name.length); }
export function chained(a) { return a.b.c().d; } /* é */ export function afterText(a) { return "é€😀" + a.b.c; }
